function renderBars(targetId,items,labelKey='model_id'){const target=$(`#${targetId}`),max=Math.max(...items.map(x=>x.requests),1);target.classList.toggle('empty',!items.length);target.innerHTML=items.length?items.map(item=>`<div><div class="bar-label"><b>${esc(item[labelKey])}</b><span>${fmtNum(item.requests)} · ${(item.requests/items.reduce((sum,row)=>sum+row.requests,0)*100).toFixed(0)}%</span></div><div class="bar-track"><i style="width:${item.requests/max*100}%"></i></div></div>`).join(''):'暂无数据'}
