  target.innerHTML=rows.length?`<div class="fairness-coverage"><span class="muted">字段覆盖率：</span>${coverage}</div><div class="table-wrap"><table><thead><tr><th>维度</th><th>分组</th><th>请求</th><th>成功率</th><th>回退率</th><th>人工 Pass</th><th>平均延迟</th><th>路由层级分配</th></tr></thead><tbody>${rows.join('')}</tbody></table></div>${gaps?`<div class="fairness-gaps"><b>最大的层级分配差异</b><ul>${gaps}</ul><p class="muted">差异可能来自请求难度、样本量或模型可用性，不能单独视为不公平证据。</p></div>`:''}`:'<div class="table-empty">暂无分组数据。可在 API 的 metadata 或批次 JSONL 中提供 language、scenario、tenant、segment。</div>';
