async function trainBatch(id,strategy='auto',button=null){try{const result=await api(`/v1/batches/${id}/train`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({strategy})});closeTrainingDialog();closeBatchWorkbench();await loadData();showTrainingResult(result)}catch(error){toast(`暂不能训练：${error.message}`);if(button){button.disabled=false;button.textContent='开始训练'}}}
async function submitRouterTraining(event){event.preventDefault();const strategy=$('input[name="router-trainer"]:checked')?.value;if(!state.trainingBatchId||!strategy)return;const button=$('#confirm-router-training');if(button.disabled)return;button.disabled=true;button.textContent='训练中…';await trainBatch(state.trainingBatchId,strategy,button)}
async function showTrace(id){try{const t=await api(`/v1/traces/${id}`);$('#dialog-title').textContent=t.trace_id;const candidates=t.decision?.candidates||t.decision?.prediction?.candidates||[];$('#dialog-body').innerHTML=`<dl class="facts"><div><dt>状态</dt><dd>${esc(statusText(t.status))}</dd></div><div><dt>路由层级</dt><dd>${esc(t.selected_route_label||'—')}</dd></div><div><dt>选择 / 实际模型</dt><dd>${esc(t.selected_model_id||'—')} / ${esc(t.actual_model_id||'—')}</dd></div><div><dt>路由原因</dt><dd>${esc(t.decision?.reason||'—')}</dd></div><div><dt>Input Token</dt><dd>${fmtNum(t.prompt_tokens)}</dd></div><div><dt>Output Token</dt><dd>${fmtNum(t.completion_tokens)}</dd></div><div><dt>延迟</dt><dd>${fmtMs(t.latency_ms)}</dd></div><div><dt>输入安全命中</dt><dd>${(t.input_findings||[]).map(f=>`<span class="tag">${esc(f.entity_type)}</span>`).join('')||'无'}</dd></div></dl><div class="detail-section"><h3>脱敏输入</h3><pre>${esc(t.input_text||'(metadata only)')}</pre></div>${t.output_text?`<div class="detail-section"><h3>脱敏输出</h3><pre>${esc(t.output_text)}</pre></div>`:''}<div class="detail-section"><h3>层级预测</h3>${candidates.map(c=>`<span class="tag">${esc(c.route_label||c.model_id)} · ${((c.probability??c.success_probability)*100).toFixed(1)}%</span>`).join('')||'—'}</div><div class="detail-section"><h3>已有反馈</h3><p>${t.annotations.length?t.annotations.map(a=>`<span class="tag ${a.passed?'good':'bad'}">${a.passed?'PASS':'FAIL'} · ${fmtDate(a.created_at)}</span>`).join(''):'尚无反馈'}</p><p class="muted">请求记录用于运行排查；正式人工标注请进入“人工标注”。</p></div>`;$('#trace-dialog').showModal()}catch(error){toast(error.message)}}
async function label(id,passed){try{await api(`/v1/traces/${id}/annotations`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({passed})});toast(passed?'已标记为 Pass':'已标记为 Fail');await loadData()}catch(error){toast(`标注失败：${error.message}`)}}
async function send(){
  const content=$('#user-input').value.trim();if(!content){toast('请输入 User message');return}
  const button=$('#send-button');button.disabled=true;$('#send-status').textContent='正在安全检查并调用模型…';
  const messages=[],system=$('#system-input').value.trim();if(system)messages.push({role:'system',content:system});messages.push({role:'user',content});
  const payload={model:'auto',messages},fields={max_tokens:'#request-max-tokens',temperature:'#request-temperature',top_p:'#request-top-p',top_k:'#request-top-k'};
  Object.entries(fields).forEach(([key,selector])=>{const value=$(selector).value;if(value!=='')payload[key]=Number(value)});
  const metadata={},metadataFields={language:'#request-language',scenario:'#request-scenario',tenant:'#request-tenant',segment:'#request-segment'};
  Object.entries(metadataFields).forEach(([key,selector])=>{const value=$(selector).value.trim();if(value)metadata[key]=value});if(Object.keys(metadata).length)payload.metadata=metadata;
  try{const result=await api('/v1/chat/completions',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload)});state.lastTrace=result.routetune.trace_id;$('#result-empty').classList.add('hidden');$('#result-content').classList.remove('hidden');$('#answer').textContent=result.choices[0].message.content;$('#result-model').textContent=result.model;$('#selected-model').textContent=result.routetune.selected_model;$('#actual-model').textContent=result.routetune.actual_model;$('#route-reason').textContent=result.routetune.route_reason;$('#result-latency').textContent=fmtMs(result.routetune.latency_ms);$('#send-status').textContent=`Trace: ${result.routetune.trace_id}`;await loadData()}catch(error){toast(`请求失败：${error.message}`);$('#send-status').textContent='请求失败，可在 Trace 中查看'}finally{button.disabled=false}
}
const providerPresets={openrouter:{display_name:'OpenRouter',base_url:'https://openrouter.ai/api/v1',api_key_env:'OPENROUTER_API_KEY'},siliconflow:{display_name:'硅基流动',base_url:'https://api.siliconflow.cn/v1',api_key_env:'SILICONFLOW_API_KEY'},deepseek:{display_name:'DeepSeek',base_url:'https://api.deepseek.com',api_key_env:'DEEPSEEK_API_KEY'},minimax:{display_name:'MiniMax',base_url:'https://api.minimaxi.com/v1',api_key_env:'MINIMAX_API_KEY'}};
function renderProviderOptions(selectedValue=null){const target=$('#model-provider');if(!target)return;const current=selectedValue??target.value,custom=state.providers.filter(p=>!providerPresets[p.provider_id]);target.innerHTML=`${Object.entries(providerPresets).map(([id,p])=>`<option value="${esc(id)}">${esc(p.display_name)}</option>`).join('')}${custom.map(p=>`<option value="custom:${esc(p.provider_id)}">自定义 · ${esc(p.display_name||p.provider_id)}</option>`).join('')}<option value="custom">＋ 新建自定义 Provider</option>`;target.value=[...target.options].some(option=>option.value===current)?current:'openrouter'}
function selectedCustomProvider(){const selected=$('#model-provider').value;if(!selected.startsWith('custom:'))return null;const providerId=selected.slice(7);return state.providers.find(p=>p.provider_id===providerId)||null}
function updateProviderHint(hydrate=false){const selected=$('#model-provider').value,existingCustom=selectedCustomProvider(),isCustom=selected==='custom'||Boolean(existingCustom);$('#custom-provider-fields').classList.toggle('hidden',!isCustom);if(isCustom){if(existingCustom&&hydrate){$('#custom-provider-id').value=existingCustom.provider_id;$('#custom-base-url').value=existingCustom.base_url;$('#custom-key-env').value=existingCustom.api_key_env;$('#custom-no-auth').checked=!existingCustom.api_key_env}const noAuth=$('#custom-no-auth').checked;$('#custom-key-env').disabled=noAuth;$('#provider-key').disabled=noAuth;$('#model-env-hint').textContent=`可创建任意多个自定义 OpenAI-compatible Provider；Provider ID 用于复用配置。${noAuth?'当前出口不发送 Authorization。':'Key 可临时注入进程，持久化请使用对应环境变量。'}`;return}const p=providerPresets[selected];$('#custom-key-env').disabled=false;$('#provider-key').disabled=false;const existing=state.models.find(m=>m.provider_id===selected&&m.api_key_available);$('#model-env-hint').textContent=`服务端环境变量：${p.api_key_env} · ${p.base_url}。${existing?'Key 当前可用。':'也可在这里临时填写 Key；重启服务后失效。'}`}
function openModelDialog(model=null){state.editingModelId=model?.model_id||null;$('#model-form').reset();$('#model-dialog-title').textContent=model?'编辑模型':'添加模型';$('#model-id').disabled=Boolean(model);if(model){const preset=providerPresets[model.provider_id],customValue=state.providers.some(p=>p.provider_id===model.provider_id)?`custom:${model.provider_id}`:'custom';renderProviderOptions(preset?model.provider_id:customValue);$('#model-id').value=model.model_id;$('#api-model').value=model.api_model;$('#model-tier').value=model.route_label;$('#cost-rank').value=model.cost_rank;$('#model-tags').value=model.tags.join(', ');$('#model-max-tokens').value=model.max_tokens??1024;$('#model-temperature').value=model.temperature??'';$('#model-top-p').value=model.top_p??'';$('#model-top-k').value=model.top_k??'';$('#model-enabled').checked=model.enabled;if(!preset){$('#custom-provider-id').value=model.provider_id;$('#custom-base-url').value=model.base_url;$('#custom-key-env').value=model.api_key_env;$('#custom-no-auth').checked=!model.api_key_env}}else{renderProviderOptions('openrouter');$('#model-enabled').checked=true}$('#provider-key').value='';updateProviderHint();$('#model-dialog').showModal()}
async function saveModel(event){event.preventDefault();const selected=$('#model-provider').value,isCustom=selected==='custom'||selected.startsWith('custom:'),preset=providerPresets[selected];const provider=isCustom?$('#custom-provider-id').value.trim():selected;const noAuth=isCustom&&$('#custom-no-auth').checked;const baseUrl=isCustom?$('#custom-base-url').value.trim():preset.base_url;const keyEnv=noAuth?'':(isCustom?$('#custom-key-env').value.trim():preset.api_key_env);if(!provider||!baseUrl){toast('自定义 Provider ID 和 Base URL 必填');return}const optionalNumber=selector=>$(selector).value===''?null:Number($(selector).value),payload={model_id:$('#model-id').value.trim(),provider_id:provider,base_url:baseUrl,api_key_env:keyEnv,api_model:$('#api-model').value.trim(),route_label:$('#model-tier').value,cost_rank:Number($('#cost-rank').value),tags:$('#model-tags').value.split(',').map(x=>x.trim()).filter(Boolean),enabled:$('#model-enabled').checked,max_tokens:Number($('#model-max-tokens').value),temperature:optionalNumber('#model-temperature'),top_p:optionalNumber('#model-top-p'),top_k:optionalNumber('#model-top-k')};try{const editing=state.editingModelId;await api(editing?`/v1/model-pool/${editing}`:'/v1/model-pool',{method:editing?'PUT':'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload)});const key=$('#provider-key').value.trim();if(key&&!noAuth)await api(`/v1/providers/${provider}/credential`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({api_key:key})});$('#model-dialog').close();state.editingModelId=null;$('#model-id').disabled=false;toast('模型池草稿已更新；请点击检测确认可用性，发布后生效');await loadHealth();await loadData()}catch(error){toast(`保存失败：${error.message}`)}}
function bindListControls(){const controls=[['trace-search','traces',renderTraces,'input'],['trace-source-filter','traces',renderTraces,'change'],['status-filter','traces',renderTraces,'change'],['model-search','models',renderModels,'input'],['model-filter','models',renderModels,'change'],['dictionary-search','dictionaries',renderSecurity,'input'],['dictionary-filter','dictionaries',renderSecurity,'change'],['batch-search','batches',renderBatches,'input'],['batch-filter','batches',renderBatches,'change'],['review-search','reviews',renderReviews,'input'],['review-filter','reviews',renderReviews,'change'],['release-search','releases',renderReleases,'input'],['release-filter','releases',renderReleases,'change']];controls.forEach(([id,key,render,event])=>{$(`#${id}`)[`on${event}`]=()=>{listViews[key].page=1;render()}});$$('[data-list-size]').forEach(select=>select.onchange=()=>{const key=select.dataset.listSize;listViews[key].size=Number(select.value);listViews[key].page=1;({traces:renderTraces,models:renderModels,dictionaries:renderSecurity,batches:renderBatches,reviews:renderReviews,releases:renderReleases})[key]()})}
$$('.nav-item').forEach(el=>el.onclick=()=>switchPage(el.dataset.page));$$('[data-go]').forEach(el=>el.onclick=()=>switchPage(el.dataset.go));$('#refresh-button').onclick=()=>{loadHealth();loadData()};$('#status-filter').onchange=renderTraces;$('#send-button').onclick=send;$('#pass-button').onclick=()=>state.lastTrace&&label(state.lastTrace,true);$('#fail-button').onclick=()=>state.lastTrace&&label(state.lastTrace,false);$('#close-dialog').onclick=()=>$('#trace-dialog').close();$('#token-button').onclick=()=>{$('#token-input').value=state.token;$('#token-dialog').showModal()};$('#save-token').onclick=()=>{state.token=$('#token-input').value.trim();if(state.token)sessionStorage.setItem('routetune_api_key',state.token);else sessionStorage.removeItem('routetune_api_key');setTimeout(()=>{loadHealth();loadData()},0)};$('#add-model-button').onclick=()=>openModelDialog();$('#close-model-dialog').onclick=$('#cancel-model').onclick=()=>{$('#model-dialog').close();state.editingModelId=null;$('#model-id').disabled=false};$('#model-provider').onchange=()=>updateProviderHint(true);$('#custom-no-auth').onchange=()=>updateProviderHint();$('#model-form').onsubmit=saveModel;$('#dictionary-form').onsubmit=importDictionary;$('#batch-form').onsubmit=importBatch;$('#refresh-batches').onclick=loadData;$('#close-batch-dialog').onclick=closeBatchWorkbench;$('#batch-dialog').addEventListener('cancel',event=>{event.preventDefault();closeBatchWorkbench()});$('#create-release-button').onclick=createRelease;
$('#dashboard-window').onchange=loadStats;
